function validate([books, shelfWidth]) {
  if (!Number.isInteger(shelfWidth) || shelfWidth < 1 || shelfWidth > 1000) return 'shelfWidth is between 1 and 1000.';
  if (books.length < 1 || books.length > 1000) return 'books needs 1 to 1000 entries.';
  for (const book of books) {
    if (!Array.isArray(book) || book.length !== 2) return 'Each book is a pair [thickness, height].';
    const [thickness, height] = book;
    if (!Number.isInteger(thickness) || thickness < 1 || thickness > shelfWidth) return 'Each thickness is between 1 and shelfWidth.';
    if (!Number.isInteger(height) || height < 1 || height > 1000) return 'Each height is between 1 and 1000.';
  }
  return null;
}

