function minHeightShelves(books, shelfWidth) {
  const n = books.length;
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;

  for (let i = 1; i <= n; i++) {
    let width = 0;
    let height = 0;
    for (let j = i; j >= 1; j--) {
      const [thickness, bookHeight] = books[j - 1];
      width += thickness;
      if (width > shelfWidth) {
        break;
      }
      height = Math.max(height, bookHeight);
      dp[i] = Math.min(dp[i], dp[j - 1] + height);
    }
  }
  return dp[n];
}

