function minHeightShelves(books, shelfWidth) {
  // Top-down over suffixes: try every first shelf, then solve the rest.
  const memo = new Map();
  const best = start => {
    if (start === books.length) return 0;
    if (memo.has(start)) return memo.get(start);
    let result = Infinity;
    for (let end = start + 1; end <= books.length; end++) {
      const shelf = books.slice(start, end);
      if (shelf.reduce((sum, book) => sum + book[0], 0) > shelfWidth) break;
      result = Math.min(result, Math.max(...shelf.map(book => book[1])) + best(end));
    }
    memo.set(start, result);
    return result;
  };
  return best(0);
}

