function generate(rand, size) {
  const pick = k => 1 + Math.floor(rand() * k);
  if (size === 'large') {
    const shelfWidth = pick(1000);
    const thick = Math.min(shelfWidth, pick(60));
    return [Array.from({ length: 1000 }, () => [pick(thick), pick(1000)]), shelfWidth];
  }
  const n = pick(10);
  const shelfWidth = pick(rand() < 0.2 ? 3 : 12);
  const tall = rand() < 0.6 ? 6 : 1000;
  return [Array.from({ length: n }, () => [pick(shelfWidth), pick(tall)]), shelfWidth];
}
